draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw chopping board
  ctx.fillStyle = '#964B00';
  ctx.fillRect(W/2-50, H/2-25, 100, 50);

  // draw onion
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(W/2-25, H/2-50, 50, 50);

  // draw knife
  ctx.fillStyle = '#808080';
  ctx.fillRect(W/2-10, H/2-10, 20, 50);
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.fillRect(-10, -25, 20, 50);
  ctx.restore();

  // draw tears
  ctx.fillStyle = '#0000FF';
  ctx.beginPath();
  ctx.arc(W/2-75, H/2-75, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2-65, H/2-85, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2-55, H/2-75, 10, 0, 2*Math.PI);
  ctx.fill();

  // draw stick figure chopping
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 25, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+25);
  ctx.lineTo(W/2, H/2+75);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-25, H/2+50);
  ctx.lineTo(W/2, H/2+75);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+25, H/2+50);
  ctx.lineTo(W/2, H/2+75);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+75);
  ctx.lineTo(W/2-10+Math.sin(t)*10, H/2+100);
  ctx.stroke();

  ctx.restore();
}
